from lxml import etree


class XML(object):

    def parse_xml(self, xml_path):
        with open(xml_path) as xml_file:
            return etree.fromstring("".join(xml_file.readlines()))

    def get_element_text(self, xml, xpath):
        return xml.find(xpath).text

    def set_element_text(self, xml, xpath, text):
        xml.find(xpath).text = text
        return xml

    def get_elements_texts(self, xml, xpath):
        return [element.text for element in xml.findall(xpath)]

    def get_element_count(self, xml, xpath):
        return len(xml.findall(xpath))

    def get_element_attribute(self, xml, name, xpath='.', default=None):
        return xml.find(xpath).attrib.get(name, default)

    def save_xml(self, xml, path):
        etree.ElementTree(xml).write(path, pretty_print=True,
                                     xml_declaration=True, encoding="utf-8")
